(** * ValueCommitV fixed-base window-point table: builders and materialised literal

    The 22 x 8 = 176 Weierstrass multiples of the ValueCommitV generator that
    both ValueCommitV certificates read:

    - the x-coordinate Lagrange certificate
      ([circuit_proof/value_commit_v/x_cert.v]);
    - the positive QR window-sign certificate
      ([circuit_proof/value_commit_v/sign_cert.v]).

    [full_table] builds the multiples through the scalar-multiplication
    composition law (Weierstrass [mul_mul]), reusing the generic builders of
    [FixedBaseTableDefs] ([nonlast_points], [base_pow8], [last_row],
    [window_offset_sum] are all generic in the base point).  Concretely:

    - [nonlast_points 21 G] builds the 21 non-last windows incrementally: window
      [w]'s row is [[(d+2)] B_w] for [d = 0..7] (i.e. [[2]B_w .. [9]B_w]), with
      [B_w = [8^w] G] threaded as the 7th row entry [[8]B_w = B_{w+1}], so the
      whole 21*8 = 168 window points share one octupling chain;
    - the last window (21) is [[d * 8^21 - window_offset_sum 21] G] for
      [d = 0..7], assembled from [B_21 = [8^21] G] ([base_pow8]) and the offset
      point [[window_offset_sum 21] G].

    [full_table_reduced] is the same table as a pasted affine-coordinate
    literal, generated once offline by [Eval vm_compute in full_table]; the
    equality [full_table_reduced_eq] is the single heavy [vm_compute] [Qed] of
    the ValueCommitV certificate stack.  The two certificate files read only
    the literal, so their own [vm_compute]s cost seconds.

    This file depends only on the elliptic-curve layer (Weierstrass/Pallas),
    the ValueCommitV generator point ([Orchard.Pallas.Generators]), and the
    shared table builders ([circuit_proof.table_defs]): iterating
    on [Field/Sqrt.v], [ecc/chip/window_disc.v],
    [ecc/chip/fixed_window_canonical.v], or the rest of the Orchard proof
    stack never invalidates it. *)

Require Import Stdlib.ZArith.ZArith.
Require Import Stdlib.Lists.List.
Require Import Garden.EllipticCurve.Weierstrass.
Require Import Garden.EllipticCurve.Pallas.
Require Import Garden.Orchard.Pallas.Generators.
Require Import Garden.Orchard.circuit_proof.table_defs.
Import ListNotations.
Global Open Scope Z_scope.

Module ValueCommitVFullTable.
  (** The ValueCommitV affine generator. *)
  Definition G : Pallas.point := PallasGenerators.value_commit_v_G.

  (** All 22 window rows (21 non-last + 1 last). *)
  Definition full_table : list (list Pallas.point) :=
    FixedBaseTableDefs.nonlast_points 21 G
    ++ [FixedBaseTableDefs.last_row
          (FixedBaseTableDefs.base_pow8 21 G)
          (Pallas.mul (FixedBaseTableDefs.window_offset_sum 21) G)].

